INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass Rankings von Programmiersprachen nur auf GitHub-Daten basieren?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Stack Overflow wird genutzt"}, {"text": "Ja", "correct": false, "because": "Mehrere Datenquellen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Plattform nutze ich neben GitHub, um Sprachenpopularität zu messen?', 3, '[{"text": "Stack Overflow", "correct": true, "because": "Misst Diskussionen"}, {"text": "Reddit", "correct": false, "because": "Kein primärer Fokus"}, {"text": "LinkedIn", "correct": false, "because": "Nicht für Code relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Sprachenranking zuverlässig?', 5, '[{"text": "Kombination von Code-Nutzung", "correct": true, "because": "Zeigt praktische Anwendung"}, {"text": "Community-Diskussionen", "correct": true, "because": "Reflektiert Interesse"}, {"text": "Farbcodierte Visuals", "correct": false, "because": "Nur Darstellung"}, {"text": "Schnelle Veröffentlichung", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) JavaScript führt oft die Rankings an. b) Es ist immer die beste Sprache.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist subjektiv"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Analyse von Programmiersprachen-Trends?', 4, '[{"text": "GitHub-Pull-Requests", "correct": false, "because": "Zeigen Nutzung"}, {"text": "Stack Overflow-Fragen", "correct": false, "because": "Reflektieren Interesse"}, {"text": "Social-Media-Likes", "correct": true, "because": "Kein direkter Indikator"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Python in Rankings oft hoch platziert ist?', 2, '[{"text": "Ja", "correct": true, "because": "Starke Community und Nutzung"}, {"text": "Nein", "correct": false, "because": "Python ist top-platziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sprache hat laut Analysen in den letzten Jahren stark an Popularität gewonnen?', 4, '[{"text": "TypeScript", "correct": true, "because": "Steigende Nutzung in Webentwicklung"}, {"text": "COBOL", "correct": false, "because": "Ältere Sprache, wenig Wachstum"}, {"text": "Pascal", "correct": false, "because": "Geringe moderne Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Rankings die Zukunft von Sprachen vorhersagen können. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Nur Trends, keine Prognosen"}, {"text": "Ja", "correct": false, "because": "Zu unsicher für Vorhersagen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Sprachen wie Rust in den Top 10?', 2, '[{"text": "Nein", "correct": true, "because": "Meist Top 20, nicht Top 10"}, {"text": "Ja", "correct": false, "because": "Noch nicht so hoch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenquellen helfen, die Beliebtheit einer Sprache zu bewerten?', 5, '[{"text": "GitHub-Projekte", "correct": true, "because": "Zeigen tatsächliche Nutzung"}, {"text": "Stack Overflow-Diskussionen", "correct": true, "because": "Reflektieren Community"}, {"text": "YouTube-Tutorials", "correct": false, "because": "Indirekter Indikator"}, {"text": "Blog-Artikel", "correct": false, "because": "Subjektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Interpretation eines Sprachenrankings?', 4, '[{"text": "Tier-Gruppierungen", "correct": true, "because": "Zeigen relative Popularität"}, {"text": "Exakte Platzierung", "correct": false, "because": "Oft wenig Unterschied"}, {"text": "Veröffentlichungsdatum", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rankings kombinieren Code und Diskussionen. b) Sie messen nur aktuelle Nutzung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Trends im Fokus"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um die Popularität einer Sprache zu bewerten?', 3, '[{"text": "GitHub-Daten", "correct": false, "because": "Zeigen Nutzung"}, {"text": "Stack Overflow", "correct": false, "because": "Reflektiert Diskussionen"}, {"text": "Farbschema von Code", "correct": true, "because": "Kein Indikator"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich Trends in Sprachen analysieren würde?', 4, '[{"text": "GitHub und Stack Overflow kombinieren", "correct": true, "because": "Gibt breites Bild"}, {"text": "Nur Jobanzeigen prüfen", "correct": false, "because": "Eingeschränkt"}, {"text": "Social Media scannen", "correct": false, "because": "Unzuverlässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass JavaScript immer Platz 1 hält. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Oft führend durch Webnutzung"}, {"text": "Nein", "correct": false, "because": "JavaScript meist ganz oben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, die Stabilität eines Rankings zu bewerten?', 3, '[{"text": "Langzeitbeobachtung", "correct": true, "because": "Zeigt konsistente Trends"}, {"text": "Einmalige Momentaufnahme", "correct": false, "because": "Zu begrenzt"}, {"text": "Zufällige Umfragen", "correct": false, "because": "Unzuverlässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist PHP in Rankings immer noch relevant?', 2, '[{"text": "Ja", "correct": true, "because": "Hält sich in Top 10"}, {"text": "Nein", "correct": false, "because": "PHP bleibt populär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sprachen haben laut Analysen an Popularität verloren?', 5, '[{"text": "Objective-C", "correct": true, "because": "Abgelöst durch Swift"}, {"text": "PHP", "correct": true, "because": "Leichter Rückgang erkennbar"}, {"text": "Python", "correct": false, "because": "Bleibt stark"}, {"text": "JavaScript", "correct": false, "because": "Führend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung von Sprachenrankings unwichtig?', 3, '[{"text": "Datenquellen", "correct": false, "because": "Bestimmen Zuverlässigkeit"}, {"text": "Langzeittrends", "correct": false, "because": "Zeigen Entwicklung"}, {"text": "Veröffentlichungsdesign", "correct": true, "because": "Kein Einfluss auf Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich die Relevanz einer Sprache prüfen will?', 4, '[{"text": "Code-Nutzung und Diskussionen analysieren", "correct": true, "because": "Gibt umfassendes Bild"}, {"text": "Nur Tutorials zählen", "correct": false, "because": "Zu einseitig"}, {"text": "Einzelne Blogs lesen", "correct": false, "because": "Subjektiv"}]');
